out=[[0]*26 for _ in range(22)]
# Frame outlines: (row range inclusive, col range inclusive, color)
frames=[(1,6,3,11,1),(10,13,2,5,2),(9,16,11,21,3)]
for r0,r1,c0,c1,col in frames:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1): out[r][c]=col
# checker fills, using upper-left interior cell as colored
fills=[(2,5,4,10,4),(11,12,3,4,8),(10,15,12,20,5)]
for r0,r1,c0,c1,col in fills:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r-r0+c-c0)%2==0: out[r][c]=col
print('\n'.join(' '.join(map(str,r)) for r in out))
print('count fill',sum(x==4 for r in out for x in r),sum(x==8 for r in out for x in r),sum(x==5 for r in out for x in r))
